B.push(
{id:"M1-01",m:1,q:"¿Cuál es el objetivo principal de la Ley 26.831?",o:["Fijar el precio de los valores negociables listados","Regular, supervisar y fiscalizar el mercado de capitales","Garantizar un rendimiento mínimo al inversor minorista","Administrar el sistema previsional argentino"],a:1,e:"La 26.831 es la Ley de Mercado de Capitales: regula, supervisa y fiscaliza. Nunca garantiza precios ni rentabilidad.",r:"M1 · P1"},
{id:"M1-02",m:1,q:"¿Qué organismo es la autoridad de aplicación de la Ley 26.831?",o:["El Banco Central de la República Argentina","La Unidad de Información Financiera","La Comisión Nacional de Valores","El Ministerio de Economía"],a:2,e:"La CNV es la autoridad de aplicación de la Ley de Mercado de Capitales. La UIF lo es de la Ley 25.246 (lavado).",r:"M1 · P2"},
{id:"M1-03",m:1,q:"¿Cuál de las siguientes NO es una facultad de la Comisión Nacional de Valores?",o:["Garantizar la rentabilidad de los inversores","Llevar el registro de los agentes","Dictar normas reglamentarias","Aplicar sanciones previo sumario"],a:0,e:"La CNV protege al inversor y fiscaliza, pero jamás garantiza resultados económicos. Clásico distractor de examen.",r:"M1 · P3"},
{id:"M1-04",m:1,q:"¿Qué principio rige la adquisición de acciones propias por parte de una emisora?",o:["Prioridad del accionista controlante","Trato igualitario entre todos los accionistas","Preferencia de los accionistas con más antigüedad","Libre discrecionalidad del directorio"],a:1,e:"Toda recompra de acciones propias debe respetar el trato igualitario entre accionistas.",r:"M1 · P4"},
{id:"M1-05",m:1,q:"¿Qué documento debe presentar una emisora para solicitar la autorización de oferta pública?",o:["El acta de directorio","La memoria anual","El prospecto","El código de gobierno societario"],a:2,e:"El prospecto es el documento básico que se acompaña al solicitar el ingreso a la oferta pública.",r:"M1 · P5"},
{id:"M1-06",m:1,q:"¿Cuál es el plazo mínimo para aceptar una OPA una vez publicada?",o:["5 días hábiles","10 días hábiles","20 días hábiles","30 días corridos"],a:1,e:"El plazo de aceptación de una OPA nunca puede ser menor a 10 días hábiles.",r:"M1 · P6"},
{id:"M1-07",m:1,q:"¿Qué sucede si una oferta pública se realiza sin autorización de la CNV?",o:["Se considera oferta irregular","Queda convalidada si se informa dentro de las 48 horas","Es válida si se dirige sólo a inversores calificados","Debe ser autorizada por el mercado donde se liste"],a:0,e:"Sin autorización previa de la CNV, la oferta es irregular y expone a sanciones.",r:"M1 · P7"},
{id:"M1-08",m:1,q:"¿Qué es la DUVA según la Ley 26.831?",o:["Declaración Única de Valores Admitidos","Declaración Unilateral de Adquisición","Documento Unificado de Valuación de Activos","Dictamen Único de Valuación Accionaria"],a:1,e:"DUVA: Declaración Unilateral de Voluntad de Adquisición. Se usa en el régimen de participaciones residuales.",r:"M1 · P8"},
{id:"M1-09",m:1,q:"¿Cuál es la sanción máxima prevista por la Ley 26.831 para incumplimientos graves?",o:["Multa hasta el doble del beneficio obtenido","Multa hasta el triple del beneficio obtenido","Multa hasta el quíntuplo del beneficio obtenido","Multa hasta el décuplo del beneficio obtenido"],a:2,e:"El tope es el quíntuplo (5 veces) del beneficio obtenido o del perjuicio ocasionado.",r:"M1 · P9"},
{id:"M1-110",m:1,q:"¿Qué condición debe cumplir una PyME para ingresar al régimen PyME CNV?",o:["Contar con una calificación de riesgo emitida por un agente registrado","Tener patrimonio neto positivo en sus últimos tres balances","Obtener el aval de una SGR para cada una de sus emisiones","Cumplir con los parámetros establecidos por la SEPyME"],a:3,e:"Según la guía, lo que define el ingreso al régimen PyME CNV es cumplir los parámetros establecidos por la SEPyME, no una calificación de riesgo ni un requisito patrimonial.",r:"M1 · P10"},
{id:"M1-111",m:1,q:"¿Qué significa “oferta pública” según la Ley 26.831?",o:["Una oferta dirigida sólo a inversores calificados previamente identificados","Una oferta hecha por el emisor a sus propios accionistas en forma privada","Una oferta dirigida al público en general o a sectores indeterminados","Una oferta que se negocia exclusivamente en un mercado del exterior"],a:2,e:"Según la guía, lo que hace pública a una oferta es que se dirige al público en general o a sectores indeterminados, no a destinatarios elegidos de antemano.",r:"M1 · P11"},
{id:"M1-47",m:1,q:"¿Qué norma regula el secreto profesional en el mercado de capitales?",o:["Ley 25.246, art. 21","Ley 26.831, art. 24","Ley 19.550, art. 274","Ley 24.083, art. 1"],a:1,e:"La guía ubica el secreto en la propia Ley de Mercado de Capitales, art. 24. La 25.246 es la de lavado y la 24.083 la de FCI.",r:"M1 · P12"},
{id:"M1-12",m:1,q:"¿Cuál es la función del Tribunal Arbitral según la Ley 26.831?",o:["Resolver controversias entre participantes del mercado","Aplicar las sanciones que dispone la CNV","Autorizar las ofertas públicas de adquisición","Homologar los prospectos de emisión"],a:0,e:"El tribunal arbitral de los mercados resuelve controversias entre participantes; no sanciona ni autoriza.",r:"M1 · P13"},
{id:"M1-48",m:1,q:"¿Qué debe incluir el prospecto de emisión?",o:["Sólo las condiciones de emisión, el precio de colocación y la identidad del agente colocador","La opinión de la CNV sobre la conveniencia económica de invertir en los valores","Únicamente los estados contables auditados de los últimos tres ejercicios","Información financiera, riesgos, características de los valores y datos del emisor"],a:3,e:"El prospecto tiene que darle al inversor el cuadro completo: números, riesgos, qué valor compra y quién lo emite.",r:"M1 · P14"},
{id:"M1-13",m:1,q:"¿Qué plazo tiene la emisora para informar a la CNV la designación de autoridades?",o:["24 horas","5 días hábiles","10 días hábiles","30 días corridos"],a:2,e:"10 días hábiles. No confundir con el hecho relevante, que se informa en forma inmediata.",r:"M1 · P15"},
{id:"M1-14",m:1,q:"¿Qué sucede si una emisora no coloca los valores autorizados en el plazo previsto?",o:["Debe abonar una multa equivalente al 1% del monto","La CNV cancela la autorización de oferta pública","El mercado suspende el listado por 90 días","Se prorroga automáticamente por un año"],a:1,e:"Vencido el plazo sin colocación, la CNV cancela la autorización otorgada.",r:"M1 · P16"},
{id:"M1-49",m:1,q:"¿Qué principio debe respetarse en toda OPA?",o:["Igualdad de trato y transparencia","Prioridad del accionista controlante","Libre fijación del precio por el oferente","Preferencia de los inversores institucionales"],a:0,e:"En una OPA todos los accionistas destinatarios tienen que recibir el mismo trato, con información transparente.",r:"M1 · P17"},
{id:"M1-15",m:1,q:"¿Qué plazo tiene la CNV para resolver la solicitud de autorización de una OPA?",o:["10 días hábiles","15 días hábiles","20 días hábiles","30 días hábiles"],a:2,e:"Según la guía, la CNV tiene 20 días hábiles para resolver la solicitud de autorización de una OPA.",r:"M1 · P18"},
{id:"M1-16",m:1,q:"¿Qué sucede si el oferente incumple la obligación de formular una OPA?",o:["La CNV dispone la subasta de las participaciones adquiridas","Se le aplica una inhabilitación automática de 5 años","La operación queda sin efecto de pleno derecho","El mercado retiene los valores hasta que regularice"],a:0,e:"La consecuencia típica del incumplimiento del deber de OPA es la subasta de las participaciones adquiridas.",r:"M1 · P19"},
{id:"M1-112",m:1,q:"¿Qué es una oferta pública irregular?",o:["Una oferta autorizada que no alcanzó el monto mínimo de colocación","Una oferta hecha fuera del horario de negociación del mercado","Una oferta sin autorización de la Comisión Nacional de Valores","Una oferta dirigida exclusivamente a inversores calificados"],a:2,e:"Según la guía, la oferta pública es irregular cuando se hace sin la autorización de la CNV.",r:"M1 · P20"},
{id:"M1-17",m:1,q:"¿Qué condición deben cumplir los aportes irrevocables a cuenta de futuras emisiones?",o:["Estar garantizados por una entidad financiera","Tener contrapartida en un rubro de alta liquidez","Ser aprobados por la CNV antes de su integración","Representar como máximo el 10% del capital social"],a:1,e:"Según la guía, los aportes irrevocables a cuenta de futuras emisiones tienen que tener contrapartida en un rubro de alta liquidez.",r:"M1 · P21"},
{id:"M1-18",m:1,q:"¿Qué plazo tiene la emisora para tratar en asamblea la capitalización de aportes irrevocables?",o:["3 meses","6 meses","12 meses","Hasta la próxima asamblea ordinaria"],a:1,e:"6 meses desde la aceptación del aporte.",r:"M1 · P22"},
{id:"M1-50",m:1,q:"¿Qué norma establece la responsabilidad de los administradores hacia la sociedad por los daños causados?",o:["Código Civil y Comercial, art. 146","Ley General de Sociedades, art. 234","Ley General de Sociedades, art. 274","Ley 23.576, art. 1"],a:2,e:"La guía la ubica en el art. 274 de la LGS. El 146 del CCCN es personalidad jurídica y el 234 LGS, la asamblea ordinaria.",r:"M1 · P23"},
{id:"M1-51",m:1,q:"¿Qué artículo del Código Civil y Comercial define la personalidad jurídica?",o:["Art. 19","Art. 274","Art. 146","Art. 765"],a:2,e:"Según la guía, es el art. 146 del CCCN, que figura en la bibliografía del módulo.",r:"M1 · P24"},
{id:"M1-19",m:1,q:"¿Qué plazo tiene el oferente para publicar el prospecto de una OPA luego de su aprobación?",o:["Inmediatamente","5 días hábiles","10 días hábiles","20 días hábiles"],a:1,e:"5 días hábiles para publicar el prospecto; 10 días hábiles es el plazo mínimo de aceptación.",r:"M1 · P25"},
{id:"M1-113",m:1,q:"¿Qué plazo mínimo debe durar la aceptación de una OPA?",o:["15 días corridos","3 días hábiles","30 días hábiles","10 días hábiles"],a:3,e:"La guía repite el dato: la aceptación de una OPA tiene que durar como mínimo 10 días hábiles.",r:"M1 · P26"},
{id:"M1-20",m:1,q:"¿Qué norma regula las Obligaciones Negociables en Argentina?",o:["Ley 24.083","Ley 23.576","Ley 24.441","Ley 27.440"],a:1,e:"Ley 23.576 = ON. 24.083 = FCI, 24.441 = fideicomisos, 27.440 = financiamiento productivo.",r:"M1 · P27"},
{id:"M1-52",m:1,q:"¿Qué debe contener el anuncio de una OPA?",o:["La identificación del oferente, el tipo de oferta y sus condiciones esenciales","Sólo el precio ofrecido por acción y la fecha de liquidación de la oferta","La nómina de accionistas que ya comprometieron su aceptación a la oferta","El dictamen de la CNV sobre el precio equitativo y la conveniencia de aceptar la oferta"],a:0,e:"El anuncio tiene que decir quién ofrece, qué tipo de oferta es y en qué condiciones esenciales.",r:"M1 · P28"},
{id:"M1-114",m:1,q:"¿Qué plazo tiene la Comisión Nacional de Valores para objetar el precio equitativo en una OPA?",o:["15 días hábiles","20 días hábiles","30 días corridos","60 días corridos"],a:1,e:"Según la guía, la CNV tiene 20 días hábiles para objetar el precio equitativo, el mismo plazo que para resolver la solicitud de autorización de la OPA.",r:"M1 · P29"},
{id:"M1-21",m:1,q:"¿Qué sucede si una emisora decide retirarse del régimen de oferta pública?",o:["Debe formular una OPA por el total de acciones","Basta con notificar a la CNV con 30 días de anticipación","Debe rescatar las acciones a valor libro","Debe fusionarse con otra emisora listada"],a:0,e:"El retiro obliga a formular OPA por la totalidad de las acciones (OPA por retiro).",r:"M1 · P30"},
{id:"M1-22",m:1,q:"Un Emisor Frecuente, con Registro vigente y Prospecto actualizado en la AIF, ¿cuándo debe informar la intención de una nueva emisión?",o:["Con 10 días hábiles de anticipación","Con 48 horas de anticipación","No debe informarlo previamente a la CNV mientras mantenga su condición y documentación actualizada","Sólo si supera el 20% del monto del programa"],a:2,e:"Ese es justamente el beneficio del régimen de Emisor Frecuente: con la condición y la documentación al día, no tiene que avisarle antes a la CNV.",r:"M1 · P31"},
{id:"M1-10",m:1,q:"¿Qué se entiende por PyME CNV al sólo efecto del acceso al mercado de capitales, de acuerdo a las Normas (N.T. 2013)?",o:["La que factura menos de un millón de UVA por año","La que cuenta con “Certificado MiPyME” y se encuentra, por ende, inscripta en el Registro de Empresas MiPyME a cargo de la autoridad de aplicación de la Ley Nº 24.467","La que tiene menos de 50 empleados registrados","La que no cotiza acciones en ningún mercado"],a:1,e:"Según la guía, es PyME CNV la que tiene el Certificado MiPyME y, por eso, está inscripta en el Registro de Empresas MiPyME de la autoridad de aplicación de la Ley 24.467.",r:"M1 · P32"},
{id:"M1-115",m:1,q:"“Reales S.A.” es una sociedad que quiere ingresar al régimen de oferta pública para la emisión de obligaciones negociables. Lo consultan a Ud. para saber si en la presentación inicial bajo el régimen general, ante la Comisión Nacional de Valores, el Prospecto debe ser acompañado en dicha presentación. Su respuesta es:",o:["No, el Prospecto se presenta recién una vez otorgada la autorización de oferta pública","Sí, porque es un documento básico que se debe acompañar al solicitar el ingreso a la oferta pública","No, porque para obligaciones negociables alcanza con presentar los estados contables auditados","Sí, pero sólo si la emisión también va a colocarse en el exterior"],a:1,e:"El Prospecto no es un trámite posterior: según la guía, es un documento básico que va con la solicitud de ingreso a la oferta pública.",r:"M1 · P33"},
{id:"M1-53",m:1,q:"\"Reales S.A.\", en el régimen de oferta pública, quiere emitir ON cuyos fondos irán a un proyecto de Bonos Verdes. ¿La emisión cumple con los requisitos de la CNV?",o:["Sí, siempre que un Agente de Calificación de Riesgo la califique como verde, aunque no esté admitida por ningún mercado","No, porque los bonos verdes sólo pueden emitirse bajo el régimen PyME CNV Garantizada con aval de una SGR","No, porque los bonos verdes necesitan una ley especial del Congreso que autorice cada emisión en particular","Sí, si cumple los Lineamientos para la Emisión de Valores Negociables Sociales, Verdes y Sustentables en Argentina y lo admite un mercado"],a:3,e:"Dos condiciones: seguir los Lineamientos SVS de la CNV y estar admitida por un mercado.",r:"M1 · P34"},
{id:"M1-54",m:1,q:"\"Reales S.A.\" quiere refinanciar deudas integrando ON sin oferta pública y/o créditos preexistentes. Se considera cumplido el requisito de colocación por oferta pública si esos acreedores suscriben la nueva emisión por un porcentaje que:",o:["No exceda el 50% del monto efectivamente colocado, y el resto se integre en efectivo o en especie con valores negociables con oferta pública y listado","No exceda el 30% del monto efectivamente colocado, y el resto se integre en efectivo o en especie con ON colocadas por oferta pública u otros valores con oferta pública y listado","Supere el 30% del monto efectivamente colocado, siempre que el porcentaje restante se integre únicamente en efectivo y no en especie","No exceda el 30% del monto efectivamente colocado, y el resto se integre con otras ON sin oferta pública o créditos preexistentes contra la sociedad"],a:1,e:"El tope para los acreedores que canjean deuda sin oferta pública es el 30% de lo colocado; el resto tiene que venir en efectivo o en valores con oferta pública.",r:"M1 · P35"},
{id:"M1-11",m:1,q:"Constituye oferta pública:",o:["La negociación privada de valores negociables entre dos sociedades anónimas, acordada sin publicidad y con contrapartes identificadas de antemano","La invitación que se hace a personas en general o a grupos o sectores determinados para la suscripción de valores negociables efectuada por el propio emisor por medio de publicaciones periodísticas, comunicaciones electrónicas, volantes en la vía pública, transmisiones telefónicas, de televisión, proyecciones cinematográficas y colocación de afiches","Únicamente la colocación primaria de valores negociables realizada dentro de un mercado autorizado, excluidas las invitaciones que el propio emisor haga por medios masivos de difusión","Sólo la invitación dirigida a inversores calificados por un agente registrado, siempre que se haga por medios electrónicos y no por publicaciones periodísticas ni afiches"],a:1,e:"Según la guía, la oferta pública es la invitación a personas en general o a grupos o sectores determinados para suscribir valores negociables, hecha por el propio emisor a través de medios de difusión como diarios, medios electrónicos, volantes, teléfono, TV, cine o afiches.",r:"M1 · P36"},
{id:"M1-55",m:1,q:"Constituye, entre otros, valor negociable:",o:["Las letras de cambio y las obligaciones negociables","Las cuotas sociales de una sociedad de responsabilidad limitada","Los saldos depositados en una caja de ahorro bancaria","Los contratos de locación de inmuebles urbanos"],a:0,e:"La guía da como ejemplo de valores negociables a las letras de cambio y las ON.",r:"M1 · P37"},
{id:"M1-56",m:1,q:"Cuando una sociedad realiza una emisión de obligaciones negociables con oferta pública, debe:",o:["Publicar el aviso únicamente en un diario de gran circulación nacional","Notificar la emisión a cada inversor por carta documento certificada","Publicar el aviso de emisión en la Autopista de la Información Financiera","Inscribir la emisión en el registro de sujetos obligados de la Unidad de Información Financiera"],a:2,e:"El aviso de emisión se publica en la AIF de la CNV.",r:"M1 · P38"},
{id:"M1-57",m:1,q:"Dados S.A. se fusiona por absorción con su controlada Tableros S.A. emitiendo nuevas acciones, y en el Prospecto deciden omitir los factores de riesgo sobre su apalancamiento y liquidez y sus efectos en la fusión. Ud. opina:",o:["Es correcto omitirlos, porque la fusión sin erogación de dinero mejora sus flujos financieros y reduce su riesgo","Resulta fundamental incluir en el Prospecto de fusión los riesgos de su situación de apalancamiento y liquidez y sus efectos","Alcanza con informarlos después como hecho relevante en la AIF, una vez concretada la fusión por absorción","Sólo deben incluirse si la CNV los requiere expresamente durante el trámite de autorización"],a:1,e:"El prospecto existe para mostrar los riesgos: el apalancamiento y la liquidez, y cómo pegan en la fusión, no se pueden omitir.",r:"M1 · P39"},
{id:"M1-58",m:1,q:"De acuerdo a la Ley de Mercado de Capitales, para que exista \"actuación concertada\" debe existir:",o:["La tenencia individual, directa o indirecta, de más del 50% de los votos de una emisora admitida a la oferta pública","Un acuerdo escrito e inscripto ante la CNV entre al menos tres accionistas para votar en bloque en las asambleas de la emisora","La actuación coordinada de dos o más personas para operar cualquier activo financiero, esté o no admitido a la oferta pública","La actuación coordinada de dos o más personas, por acuerdo formal o informal, para cooperar activamente en adquirir, tener o disponer acciones de una entidad en oferta pública"],a:3,e:"Hacen falta dos o más personas coordinadas por un acuerdo (formal o informal) para adquirir, tener o disponer de acciones o convertibles de una entidad en oferta pública.",r:"M1 · P40"},
{id:"M1-23",m:1,q:"El registro de accionistas de una sociedad emisora está a cargo de:",o:["La CNV exclusivamente","El mercado donde listan las acciones","La propia emisora, bancos o Caja de Valores","Un escribano público designado por la asamblea"],a:2,e:"Puede llevarlo la propia emisora, un banco o la Caja de Valores (agente de depósito colectivo).",r:"M1 · P41"},
{id:"M1-24",m:1,q:"Las acciones preferidas con preferencia patrimonial:",o:["Nunca otorgan derecho de voto","Tendrán derecho de voto si la sociedad está en mora en pagar los beneficios que constituyen su preferencia","Votan siempre con voto múltiple","Se convierten automáticamente en ordinarias a los 5 años"],a:1,e:"La mora en el pago de la preferencia devuelve el voto a las preferidas.",r:"M1 · P42"},
{id:"M1-25",m:1,q:"Una vez en el régimen de oferta pública por acciones:",o:["Pueden emitirse acciones de voto múltiple con autorización de la asamblea","No pueden emitirse acciones ordinarias con voto privilegiado, salvo en casos de ajuste de capital","Todas las acciones deben ser preferidas","El voto plural requiere aprobación de la CNV"],a:1,e:"Prohibición del voto plural en oferta pública, con la excepción del ajuste de capital.",r:"M1 · P43"},
{id:"M1-26",m:1,q:"La colocación primaria de valores negociables deberá efectuarse mediante:",o:["Negociación bilateral entre agentes","Formación de libro o subasta o licitación pública","Venta directa del emisor a inversores calificados","Adjudicación proporcional entre los accionistas"],a:1,e:"Book building (formación de libro) o subasta/licitación pública. Vale para valores negociables y también para valores fiduciarios.",r:"M1 · P44"},
{id:"M1-27",m:1,q:"En una OPA, el oferente debe contar con una garantía emitida por:",o:["Cualquier sociedad con patrimonio neto suficiente","Entidades financieras locales o extranjeras con sucursal o representación permanente en el país, o compañías de seguros fiscalizadas por la SSN, previa autorización de la CNV","El mercado donde listan las acciones","La Caja de Valores"],a:1,e:"Entidades financieras (locales o extranjeras con presencia permanente) o aseguradoras SSN, siempre con autorización previa de la CNV.",r:"M1 · P45"},
{id:"M1-28",m:1,q:"La negociación de Cheques de Pago Diferido avalados emitidos por una PyME requiere:",o:["El aval de una SGR para su negociación en el mercado","La calificación de riesgo de un ACR","El endoso del banco girado","Autorización expresa de la CNV para cada cheque"],a:0,e:"En el segmento avalado, el cheque de pago diferido de la PyME se negocia en el mercado con el aval de una Sociedad de Garantía Recíproca.",r:"M1 · P46"},
{id:"M1-59",m:1,q:"AGRICOLA FEDERAL S.A. necesita u$s100.000.000 para un proyecto de inversión. ¿En cuál de estos instrumentos debe requerirse la previa autorización de oferta pública ante la CNV?",o:["Un préstamo otorgado por un banco del exterior con garantía hipotecaria sobre sus campos","Un préstamo sindicado otorgado por un grupo de bancos locales","Un contrato de leasing financiero sobre la maquinaria del proyecto","Emisión primaria de acciones a ser ofrecidas y colocadas en el país y en el exterior"],a:3,e:"Ofrecer y colocar acciones en el país es oferta pública y necesita autorización previa de la CNV; los préstamos y el leasing no.",r:"M1 · P47"},
{id:"M1-29",m:1,q:"LA VIÑA S.A. pide ingresar a la oferta pública para emitir acciones y tiene patrimonio neto negativo. ¿Qué responde?",o:["No puede ingresar: el patrimonio neto positivo es requisito excluyente","La CNV autoriza el ingreso en la medida en que los riesgos de la emisora estén explicados en el prospecto","Puede ingresar sólo bajo el régimen PyME CNV Garantizada","Debe primero capitalizar y recién luego solicitar el ingreso"],a:1,e:"La CNV no evalúa la conveniencia económica: exige transparencia. Con los factores de riesgo explicados en el prospecto, autoriza.",r:"M1 · P48"},
{id:"M1-60",m:1,q:"Lost Cities Inc., holding extranjera listada en el TSX Ventures de Toronto, sin activos fijos en Canadá y con concesiones de gas y petróleo en Salta y Río Negro a través de su subsidiaria, solicita el ingreso a la oferta pública. Sus principales factores de riesgo son:",o:["Que la sucursal inscripta según el art. 118 LGS le impide listar sus acciones en la Argentina","Que la holding depende de los resultados de sus subsidiarias para cumplir sus obligaciones contractuales y pagar dividendos","Que por listar en el TSX Ventures de Toronto no puede ingresar a la oferta pública local","Que al no tener activos fijos en Canadá queda exenta de informar factores de riesgo en el prospecto"],a:1,e:"Una holding no genera fondos propios: paga deudas y dividendos con lo que le giran sus subsidiarias, y ese es su riesgo principal.",r:"M1 · P49"},
{id:"M1-30",m:1,q:"Las personas jurídicas sujetas a control societario de la CNV deben solicitar la inscripción registral de:",o:["Los miembros del Directorio","Todos los apoderados con firma","Los accionistas con más del 5%","Los gerentes de primera línea"],a:0,e:"La designación y cesación de directores se publica en el Boletín Oficial y se inscribe ante la CNV.",r:"M1 · P50"},
{id:"M1-116",m:1,q:"Las siguientes personas jurídicas se encuentran bajo control societario de la Comisión Nacional de Valores:",o:["Todas las sociedades anónimas del país, hagan o no oferta pública de sus valores","Sólo las entidades financieras autorizadas por el BCRA que emitan valores negociables","Todas las entidades encuadradas en la Ley Nº 22.169, excluidas las PyME CNV Garantizadas","Todas las entidades encuadradas en la Ley Nº 22.169, incluidas las PyME CNV Garantizadas"],a:2,e:"Según la guía, el control societario de la CNV alcanza a las entidades de la Ley 22.169, salvo las PyME CNV Garantizadas, que siguen bajo el Registro Público de su jurisdicción.",r:"M1 · P51"},
{id:"M1-117",m:1,q:"Las Sociedades de Garantía Recíproca tienen por objeto principal:",o:["Otorgar préstamos a sus socios protectores con fondos captados en el mercado","Negociar por cuenta propia cheques de pago diferido en el mercado","Calificar el riesgo crediticio de las PyMEs que emiten valores","Otorgar garantías a sus socios partícipes mediante la celebración de contratos"],a:3,e:"Según la guía, la SGR existe para garantizar: otorga garantías a sus socios partícipes a través de contratos.",r:"M1 · P52"},
{id:"M1-61",m:1,q:"Las Sociedades de Responsabilidad Limitada que califican como PyMEs CNV tienen un tope máximo de emisión:",o:["Fijado por la asamblea extraordinaria, sin parámetros de la CNV","Equivalente al monto de su capital social","Estipulado por parámetros de la CNV y resolución de su Reunión de Socios","Fijado por la SEPyME, sin intervención de la Reunión de Socios"],a:2,e:"El tope surge de dos fuentes: los parámetros de la CNV y lo que resuelva la Reunión de Socios de la SRL.",r:"M1 · P53"},
{id:"M1-62",m:1,q:"¿Debe incluirse como factor de riesgo en el Prospecto de una emisión de acciones unos préstamos de capital de trabajo próximos a vencer, garantizados con las participaciones de la Sociedad a través de una subsidiaria?",o:["Sí, hay que incluirlos porque son factores de riesgo a pesar de que estén próximos a vencer","No, porque al estar próximos a vencer dejan de ser relevantes para el inversor","Sólo si la garantía la otorga directamente la emisora y no a través de una subsidiaria","No, alcanza con que figuren en las notas a los estados contables de la emisora"],a:0,e:"Que estén por vencer no les quita el carácter de riesgo: hay que exponerlos en el prospecto.",r:"M1 · P54"},
{id:"M1-31",m:1,q:"Los responsables por la información contenida en el Prospecto son:",o:["Únicamente el emisor","Únicamente el directorio y la comisión fiscalizadora","Los emisores, los oferentes, quienes lo firmen y los expertos o terceros que opinen sobre partes del Prospecto","El agente colocador y el mercado donde se liste"],a:2,e:"La responsabilidad es amplia: emisor, oferentes, firmantes y expertos, cada uno por la parte que le toca.",r:"M1 · P55"},
{id:"M1-32",m:1,q:"Los valores negociables comprendidos en el régimen PyME CNV:",o:["Pueden ser adquiridos por cualquier inversor","Sólo pueden ser adquiridos por inversores calificados dentro de las categorías de las Normas CNV","Sólo pueden negociarse en el segmento bilateral","Requieren calificación de riesgo obligatoria"],a:1,e:"El régimen PyME CNV está reservado a inversores calificados, por su menor exigencia informativa.",r:"M1 · P56"},
{id:"M1-63",m:1,q:"Para la emisión de ON del régimen general, el Suplemento de Prospecto de una serie se publica en la AIF:",o:["Cuando el Directorio de la CNV aprueba cada serie por resolución individual, aunque el programa esté vigente","Cuando el programa está vigente/actualizado y el Suplemento incorpora la información actualizada del Prospecto del programa global","En cualquier momento, aunque el programa global esté vencido o sin actualizar su información","Recién después de la colocación y liquidación de la serie, junto con el aviso de resultados"],a:1,e:"El suplemento se apoya en el programa global: el programa tiene que estar vigente y el suplemento traer su información actualizada.",r:"M1 · P57"},
{id:"M1-64",m:1,q:"Para saber cuál es el capital social de una sociedad emisora, puedo consultar:",o:["Sólo el registro de accionistas que lleva la Caja de Valores","La memoria anual del directorio","El prospecto del último programa de ON","El estatuto social y los estados contables"],a:3,e:"El capital social surge del estatuto y se refleja en los estados contables.",r:"M1 · P58"},
{id:"M1-65",m:1,q:"Para saber qué actividades tiene permitido desarrollar una sociedad emisora, debo revisar:",o:["El estatuto social","El registro de accionistas","La memoria anual","Las actas de directorio"],a:0,e:"Las actividades permitidas son el objeto social, que está en el estatuto.",r:"M1 · P59"},
{id:"M1-66",m:1,q:"Se requiere la presentación de una adenda al Prospecto en los siguientes casos:",o:["Cada vez que se emite una nueva serie o clase bajo el Programa vigente y actualizado","El cambio del auditor externo, del agente colocador o del agente de liquidación del Programa","Modificación de términos y condiciones, prórroga de vigencia del Programa y/o aumento del monto del Programa","La aprobación de los estados contables trimestrales o la designación de nuevos directores"],a:2,e:"La adenda va cuando cambia el Programa en sí: sus términos, su plazo de vigencia o su monto.",r:"M1 · P60"},
{id:"M1-118",m:1,q:"Según la definición de PyME CNV de las Normas CNV (T.O. 2013), las mismas deben:",o:["Cumplir con los requisitos de SEPYME","Tener una antigüedad mínima de tres ejercicios cerrados","Emitir exclusivamente cheques de pago diferido avalados","Cotizar sus acciones en un mercado autorizado por la CNV"],a:0,e:"Según la guía, la definición de PyME CNV de las Normas remite a cumplir los requisitos de la SEPyME.",r:"M1 · P61"},
{id:"M1-67",m:1,q:"El régimen informativo de las PyMEs CNV Garantizadas:",o:["Es mayor al de las PyMEs CNV","Es igual al de las PyMEs CNV","Es menor al de las PyMEs CNV","Es idéntico al del régimen general de emisoras"],a:2,e:"La Garantizada tiene un régimen informativo más liviano que la PyME CNV.",r:"M1 · P62"},
{id:"M1-68",m:1,q:"Si necesito cursar una notificación a la sociedad emisora en un trámite de autorización de oferta pública, para que sea válida y vinculante debo hacerlo a:",o:["La sede social inscripta","El domicilio real del presidente del directorio","El domicilio del agente colocador","Cualquier sucursal de la emisora"],a:0,e:"La notificación vale en la sede social inscripta de la emisora.",r:"M1 · P63"},
{id:"M1-69",m:1,q:"Una persona jurídica con domicilio en Santa Fe, bajo el régimen general de oferta pública, quiere cambiar su denominación social. Deberá:",o:["Informarlo como hecho relevante en la AIF, sin necesidad de reformar su estatuto social","Reformar su estatuto e inscribirlo sólo en el Registro Público de la Provincia de Santa Fe","Pedir autorización únicamente al mercado donde listan sus valores","Reformar su estatuto y obtener la conformidad de la CNV e inscripción en el Registro Público"],a:3,e:"Cambiar la denominación es reformar el estatuto, y en oferta pública eso necesita la conformidad de la CNV y la inscripción registral.",r:"M1 · P64"},
{id:"M1-33",m:1,q:"Al alcanzar el 95% de las acciones de una sociedad admitida al régimen de oferta pública, ante intimación del minoritario, corresponde:",o:["Que la sociedad se retire automáticamente del régimen","Que la controlante lance una Declaración Unilateral de Voluntad de Adquisición (DUVA)","Que la CNV fije el precio de rescate","Que el minoritario acepte el último precio de mercado"],a:1,e:"Régimen de participaciones residuales: al 95%, el minoritario puede intimar y la controlante debe lanzar la DUVA.",r:"M1 · P65"},
{id:"M1-70",m:1,q:"Una sociedad admitida al régimen de oferta pública para emisión de acciones quiere ingresar al régimen de emisor frecuente de obligaciones negociables. Ud. opina:",o:["Es automático, porque ya se encuentra en el régimen de oferta pública para emisión de acciones","Es posible, pero deberá ingresar como emisor de ON y cumplir con los requisitos previstos por la CNV","No es posible: el régimen de emisor frecuente está reservado a quienes no emiten acciones","Es posible, con la sola aprobación de su asamblea ordinaria"],a:1,e:"Estar en oferta pública por acciones no la hace emisora de ON: tiene que ingresar como tal y cumplir los requisitos.",r:"M1 · P66"},
{id:"M1-71",m:1,q:"Una emisora extranjera cuyas acciones listan en el mercado español y en el argentino decide retirarse del régimen de oferta pública argentino. ¿Debe realizar una OPA?",o:["No es obligatoria si las acciones listan en otro mercado con liquidez igual o mayor a la local y se garantiza mantener las tenencias y/o venderlas en esos mercados","Sí, la OPA por retiro es obligatoria en todos los casos, aunque las acciones sigan listando en un mercado del exterior","No es obligatoria nunca para las sociedades constituidas en el extranjero, cualquiera sea la liquidez de sus acciones","No es obligatoria si la asamblea extraordinaria aprueba el retiro por unanimidad de los accionistas presentes"],a:0,e:"La excepción a la OPA por retiro protege igual al inversor: sigue teniendo un mercado igual o más líquido donde mantener o vender.",r:"M1 · P67"},
{id:"M1-72",m:1,q:"Una sociedad extranjera solicita el ingreso a la oferta pública sin venta de acciones nuevas. Se trata de:",o:["Oferta pública primaria","Oferta privada","Oferta pública secundaria","Oferta extraterritorial"],a:2,e:"Si no se emiten acciones nuevas, lo que se ofrece son acciones ya existentes: es oferta secundaria.",r:"M1 · P68"},
{id:"M1-34",m:1,q:"¿Qué es un CEDEAR?",o:["Un certificado de depósito de valores extranjeros que se negocia en el país","Un bono corporativo emitido en el exterior","Un fondo común de inversión cerrado","Un contrato de futuro sobre acciones extranjeras"],a:0,e:"CEDEAR = Certificado de Depósito Argentino: representa valores extranjeros y se negocia localmente.",r:"M1 · P69"},
{id:"M1-73",m:1,q:"Una minera extranjera que cotiza en Toronto y explota oro en San Juan a través de una subsidiaria quiere ingresar a la oferta pública por acciones en la Argentina con los menores costos y requisitos. Le aconsejaría:",o:["Que ingrese por el régimen PyME CNV","Que solicite el ingreso al Régimen de Doble Listado","Que coloque sus acciones por oferta privada a 35 inversores","Que ingrese por el régimen general como una emisora local"],a:1,e:"Para quien ya lista afuera, el Doble Listado es el camino de menor costo y requisitos.",r:"M1 · P70"},
{id:"M1-74",m:1,q:"¿Qué diferencia hay entre emitir ON como PyME CNV o como PyME CNV Garantizada?",o:["Bajo la Garantizada debe presentar estados contables trimestrales y pasa al control societario de la CNV como cualquier emisora","Ninguna: las dos presentan estados contables y quedan bajo el control societario de la CNV una vez admitidas","Bajo la PyME CNV no presenta estados contables una vez admitida, y bajo la Garantizada sí debe presentarlos","Bajo la Garantizada no presenta estados contables una vez admitida, y el control societario sigue en el Registro Público de su jurisdicción"],a:3,e:"La Garantizada tiene dos alivios: no presenta estados contables una vez admitida y no pasa al control societario de la CNV.",r:"M1 · P71"},
{id:"M1-75",m:1,q:"La reventa de los valores negociables adquiridos en una Oferta Privada podrá efectuarse:",o:["Sólo a inversores calificados residentes en el país, dentro del mismo año de la adquisición","Únicamente después de un año desde la adquisición, en un mercado local","Sin limitación alguna, en cualquier mercado autorizado de la Argentina","Sin limitación cuando la transferencia se efectúe fuera de la República Argentina"],a:3,e:"Fuera del país la reventa no tiene limitación.",r:"M1 · P72"},
{id:"M1-76",m:1,q:"Una oferta de valores negociables será considerada Oferta Extraterritorial cuando reúna, entre otras, la siguiente condición:",o:["Hasta 35 adquirentes como máximo y un tope de monto expresado en UVA por cada emisión","No hay límite de potenciales inversores, ni de precio ni de monto, sin necesidad de cumplir requisito alguno","Sólo inversores calificados, con un precio mínimo de colocación fijado por la CNV","Hasta 15 potenciales inversores no calificados y sin límite para los calificados"],a:1,e:"En la oferta extraterritorial no rigen los topes de la oferta privada: ni cantidad de inversores, ni precio, ni monto.",r:"M1 · P73"},
{id:"M1-35",m:1,q:"En una Oferta Privada, las invitaciones por emisión pueden efectuarse a un número máximo de:",o:["Quince (15) potenciales inversores no calificados","Veinte (20) potenciales inversores no calificados","Cincuenta (50) potenciales inversores","No hay límite si son inversores calificados"],a:0,e:"Según la guía, las invitaciones por emisión en una Oferta Privada pueden hacerse a un máximo de 15 potenciales inversores no calificados.",r:"M1 · P74"},
{id:"M1-119",m:1,q:"Las operaciones con valores negociables en una Oferta Privada podrán ser celebradas según el siguiente detalle:",o:["Por un máximo de cincuenta (50) adquirentes","Por un máximo de treinta y cinco (35) adquirentes","Por un máximo de veinticinco (25) adquirentes","Sin límite de adquirentes si todos son inversores calificados"],a:1,e:"Según la guía, las operaciones en una Oferta Privada tienen un tope de 35 adquirentes.",r:"M1 · P75"},
{id:"M1-77",m:1,q:"Respecto de la obligación de confidencialidad en una Oferta Privada:",o:["Es irrenunciable para todas las partes, aun cuando los inversores lo consientan en forma expresa","Sólo puede renunciarla la emisora, y únicamente a favor de los inversores calificados","Podrá ser renunciada en forma expresa por los inversores y por los demás intervinientes a favor de los inversores","Sólo puede dispensarla la CNV por resolución fundada, a pedido de los intervinientes"],a:2,e:"La confidencialidad se puede renunciar en forma expresa: los inversores, y los demás intervinientes a favor de ellos.",r:"M1 · P76"},
{id:"M1-78",m:1,q:"Las Ofertas Públicas con Autorización Automática por su Bajo Impacto de Obligaciones Negociables:",o:["Son consideradas ofertas públicas autorizadas y regulares, exentas de sanciones disciplinarias por oferta pública irregular","Requieren igual una resolución expresa del Directorio de la CNV para cada emisión que se realice","Son ofertas privadas y quedan fuera del control de la CNV mientras no superen el tope en UVA","Son regulares sólo si se dirigen exclusivamente a inversores calificados"],a:0,e:"La autorización es automática, así que la oferta se considera autorizada y regular y no se la puede sancionar como irregular.",r:"M1 · P77"},
{id:"M1-79",m:1,q:"Respecto de la negociación secundaria de las ON emitidas bajo el Régimen de Autorización Automática por su Bajo Impacto:",o:["Está prohibida hasta el vencimiento de las ON, para proteger a los inversores que las suscribieron","Los mercados deben adecuar el ingreso a sus plataformas digitales para no desvirtuar la simplicidad de emisión del régimen","Sólo puede realizarse en el segmento de negociación bilateral, fuera de las pantallas del mercado","Requiere presentar antes un prospecto completo del régimen general ante el mercado"],a:1,e:"La idea del régimen es la simplicidad, y los mercados no pueden trabarla con el ingreso a sus plataformas.",r:"M1 · P78"},
{id:"M1-80",m:1,q:"Con relación al Régimen de Autorización Automática de Acciones por su Mediano Impacto, se estipula que:",o:["Pueden acogerse todos los emisores, incluidas las entidades financieras, los mercados autorizados y los de servicios públicos","Sólo pueden acogerse las entidades financieras o bancarias y los emisores de servicios públicos","Sólo pueden acogerse los emisores con participación estatal o del FGS y los sujetos a privatización","No podrán acogerse emisores sujetos a privatización, con participación estatal/FGS, entidades financieras o bancarias, mercados autorizados ni emisores de servicios públicos"],a:3,e:"El régimen deja afuera a privatizables, emisores con Estado/FGS, bancos y entidades financieras, mercados y servicios públicos.",r:"M1 · P79"},
{id:"M1-81",m:1,q:"Los remates de valores negociables, judiciales o extrajudiciales, que provengan de la ejecución de garantías reales o fideicomisos de garantía tendrán Autorización Automática para Oferta Pública siempre que:",o:["Se cumplan las normas previstas por el mercado donde se lleve a cabo la subasta","La CNV autorice cada remate en forma previa, por resolución de su Directorio","El juez interviniente lo ordene en forma expresa en la sentencia","El monto rematado no supere 1.000.000 de UVA en los últimos 12 meses"],a:0,e:"La autorización es automática: la condición es respetar las normas del mercado donde se hace la subasta.",r:"M1 · P80"},
{id:"M1-82",m:1,q:"En las Ofertas Públicas con Autorización Automática por su Bajo Impacto, el valor nominal de las acciones a emitir por suscripción inicial, si la integración es en moneda extranjera:",o:["Se usa el tipo de cambio MEP del día de la integración, para cualquier moneda","Se usa el tipo comprador del BNA del día anterior, sea o no en dólares","Se usa el Tipo de Cambio de Referencia (Com. “A” 3500 BCRA), o el tipo vendedor del BNA si no es USD","Lo fija libremente la emisora en el prospecto, al tipo de cambio que elija"],a:2,e:"Para el dólar se usa el de referencia de la Com. “A” 3500 del BCRA; para otras monedas, el vendedor del BNA.",r:"M1 · P81"},
{id:"M1-83",m:1,q:"Las emisoras comprendidas en el Régimen de Oferta Pública Automática de Acciones por su Bajo Impacto podrán:",o:["Pasar al Régimen General por acciones sólo después de formular una OPA por retiro a todos los accionistas","Permanecer en ese régimen por un máximo de 12 meses, vencidos los cuales deben retirarse de la oferta pública","Pedir el cambio al Régimen General por acciones, sin que implique retirarse de la oferta pública ni hacer una OPA por retiro","Emitir obligaciones negociables sin prospecto bajo el mismo régimen de bajo impacto"],a:2,e:"Pasar al Régimen General no es salir de la oferta pública, así que no dispara la OPA por retiro.",r:"M1 · P82"},
{id:"M1-120",m:1,q:"Para calcular el límite máximo de 7.000.000 de UVAs previsto para el Régimen de Oferta Pública Automática de Acciones por su Mediano Impacto:",o:["Se computa cada emisión de acciones por suscripción en forma independiente, sin sumar las emisiones anteriores que el Emisor haya hecho bajo el régimen","Se considerarán como parte de una misma oferta las emisiones de acciones que realice el Emisor durante el ejercicio económico en curso, desde el cierre del último balance","Se considerarán como parte de una misma oferta a todas las emisiones de acciones por suscripción que realice el Emisor bajo el régimen durante los 12 meses anteriores contados desde la última fecha de emisión","Se considerarán como parte de una misma oferta todas las emisiones hechas por el Emisor desde su ingreso al régimen, sin límite de tiempo hacia atrás"],a:2,e:"Según la guía, el tope de 7.000.000 de UVAs se mide sumando como una sola oferta todas las emisiones por suscripción del régimen de los 12 meses anteriores a la última emisión.",r:"M1 · P83"},
{id:"M1-121",m:1,q:"El Emisor Frecuente mantendrá vigente su condición bajo las siguientes condiciones:",o:["Deberá ratificar su condición en forma anual ante la CNV","Deberá ratificarla cada vez que efectúe una nueva emisión","No tendrá necesidad de ratificación periódica de su condición","Deberá renovarla cada tres años con nuevos estados contables"],a:2,e:"Según la guía, la condición de Emisor Frecuente se mantiene sin necesidad de ratificarla periódicamente.",r:"M1 · P84"},
{id:"M1-84",m:1,q:"En lo atinente al plazo de difusión para la colocación primaria de valores negociables, el mismo:",o:["Deberá ser suficiente para garantizar el adecuado conocimiento por parte del público inversor","Lo fija la CNV caso por caso en la resolución que autoriza la oferta pública","No puede superar las 24 horas desde la publicación del aviso de suscripción en la AIF","Sólo es exigible cuando la colocación se hace por subasta o licitación pública"],a:0,e:"La guía no fija un número: exige que alcance para que el público inversor conozca adecuadamente la oferta.",r:"M1 · P85"},
{id:"M1-85",m:1,q:"La actualización del Prospecto como consecuencia de la aprobación de los Estados Financieros de un nuevo ejercicio anual será:",o:["Obligatoria, dentro de los 10 días hábiles de aprobados los estados financieros anuales","Optativa, y sin necesidad de acompañar informe alguno de contador público","Obligatoria, con aprobación previa de la asamblea ordinaria que trató esos estados financieros","Optativa, acompañada de un informe de contador público independiente que opine sobre la información que contiene"],a:3,e:"Es optativa, pero si se hace va con informe de contador público independiente.",r:"M1 · P86"},
{id:"M1-37",m:1,q:"A fin de apelar una sanción aplicada por la CNV, el recurso directo se interpone y se funda:",o:["Ante la Cámara Federal en lo Contencioso Administrativo","Ante la propia Comisión Nacional de Valores","Ante el mercado donde opera el sancionado","Ante el Ministerio de Economía"],a:1,e:"Según la guía, el recurso directo contra una sanción se interpone y se funda ante la propia Comisión Nacional de Valores.",r:"M1 · P87"},
{id:"M1-122",m:1,q:"A efectos de apelar una sanción impuesta por la Comisión Nacional de Valores, el recurso directo debe interponerse y fundarse:",o:["Dentro de los 5 días hábiles de la notificación del acto recurrido","Dentro de los 10 días hábiles de la notificación del acto recurrido","Dentro de los 30 días corridos de la notificación del acto recurrido","Dentro de los 15 días hábiles desde que la sanción quede firme"],a:1,e:"Según la guía, el plazo para interponer y fundar el recurso directo es de 10 días hábiles desde la notificación del acto recurrido.",r:"M1 · P88"},
{id:"M1-38",m:1,q:"El recurso directo contra una sanción impuesta por la CNV se concederá:",o:["Siempre con efecto suspensivo","Siempre con efecto devolutivo","Con efecto devolutivo, salvo contra la multa, que será con efecto suspensivo","Con efecto suspensivo, salvo la inhabilitación"],a:2,e:"Regla: devolutivo. Excepción: la multa, que se recurre con efecto suspensivo.",r:"M1 · P89"},
{id:"M1-86",m:1,q:"A los fines de fijar sanciones, entre otras pautas de graduación, la CNV deberá tener especialmente en cuenta:",o:["Únicamente el patrimonio neto del infractor al momento de la resolución y la cotización de sus valores negociables en el mercado","La actuación individual de los miembros de los órganos de administración y fiscalización, su vinculación con el grupo de control, su carácter de independiente o externo y la magnitud de la infracción","Sólo la antigüedad del sujeto en el régimen de oferta pública y la cantidad de sanciones que recibió en los últimos cinco años","La cotización del valor negociable al cierre del día del hecho, el volumen operado en esa rueda y la opinión del mercado"],a:1,e:"La graduación mira a cada persona: qué hizo cada miembro de los órganos, si es independiente o del grupo de control, y cuán grave fue la infracción.",r:"M1 · P90"},
{id:"M1-87",m:1,q:"Las multas que imponga la CNV devengarán intereses, que no podrán exceder:",o:["Una vez y media el interés que aplica el BNA en sus operaciones de descuento de documentos comerciales","El doble del interés que aplica el BNA en sus operaciones de descuento de documentos comerciales","Una vez y media la tasa de política monetaria del BCRA","El interés que fija la CNV por resolución anual"],a:0,e:"El tope es 1,5 veces la tasa del BNA para descuento de documentos comerciales.",r:"M1 · P91"},
{id:"M1-39",m:1,q:"La prescripción de las acciones nacidas de infracciones a las Leyes 26.831 y 24.083 opera:",o:["A los 2 años","A los 3 años","A los 5 años","A los 6 años de la comisión del hecho"],a:3,e:"Según la guía, la prescripción de las acciones por infracciones a las Leyes 26.831 y 24.083 opera a los 6 años de cometido el hecho.",r:"M1 · P92"},
{id:"M1-123",m:1,q:"El plazo de la prescripción de las acciones que nacieran de las infracciones al régimen de la Ley de Mercado de Capitales N° 26.831 y de la Ley de Fondos Comunes de Inversión N° 24.083 se interrumpirá:",o:["Por la sola presentación de una denuncia ante la CNV y por cualquier pedido de informes que el organismo dirija a la emisora o al agente denunciado","Por la resolución del Directorio de la CNV que ordene la apertura del sumario y por los actos de su sustanciación: la apertura a prueba, el cierre del período probatorio y la convocatoria para alegar, con sus notificaciones","Sólo por la sentencia penal firme que condene al infractor por las mismas conductas descriptas en la Ley 26.831","Por la notificación de la sanción al infractor, sin que los actos del procedimiento sumarial previos a esa resolución tengan efecto interruptivo"],a:1,e:"Según la guía, interrumpen la prescripción la resolución del Directorio que abre el sumario y los actos del procedimiento: apertura a prueba, cierre del período probatorio y convocatoria para alegar, con sus notificaciones.",r:"M1 · P93"},
{id:"M1-88",m:1,q:"Las sanciones que puede disponer la CNV por infracciones a las Leyes 26.831 y 24.083:",o:["Pueden aplicarse de inmediato y sin sumario cuando hay urgencia","Las aplica el mercado donde opera el infractor","Deben ser aplicadas mediante resolución fundada, previo sumario","Requieren una sentencia judicial firme previa"],a:2,e:"Sin sumario previo y resolución fundada no hay sanción.",r:"M1 · P94"},
{id:"M1-89",m:1,q:"La existencia de causas penales por conductas descriptas en la Ley 26.831 que pudieran dar lugar a condenas en esa sede:",o:["Suspende el sumario de la CNV hasta que haya sentencia penal firme","No obsta a la prosecución y conclusión del trámite de los sumarios en la CNV","Obliga a la CNV a archivar el sumario","Hace que el sumario pase a tramitar en sede judicial"],a:1,e:"Las dos vías corren por separado: la causa penal no frena el sumario administrativo.",r:"M1 · P95"},
{id:"M1-90",m:1,q:"Los sumarios que inicie la CNV:",o:["Se sustancian en la misma dependencia de la CNV que formula la propuesta de cargos, para ganar celeridad","Se sustancian ante el tribunal arbitral del mercado donde opera el sumariado","Se sustancian ante la Justicia en lo Contencioso Administrativo Federal, a pedido de la CNV","Se sustancian en una dependencia de la CNV separada e independiente de la que formula la propuesta de cargos"],a:3,e:"Quien acusa no instruye: la dependencia que sustancia el sumario es distinta de la que propone los cargos.",r:"M1 · P96"},
{id:"M1-91",m:1,q:"En forma previa a la apertura a prueba del procedimiento sumarial de la CNV:",o:["Debe correrse vista al denunciante para que ofrezca la prueba y se constituya como parte del sumario","Debe notificarse al mercado donde listan los valores de la emisora para que emita un dictamen previo","Debe suspenderse el sumario por 30 días para intentar una conciliación entre el sumariado y los damnificados","Debe convocarse una audiencia preliminar para pedir explicaciones y reducir las discrepancias sobre cuestiones de hecho, concentrando pasos del procedimiento"],a:3,e:"La audiencia preliminar busca concentración, economía procesal e inmediación antes de abrir a prueba.",r:"M1 · P97"},
{id:"M1-92",m:1,q:"La CNV podrá sustanciar un sumario administrativo a emisoras, cámaras compensadoras, agentes y a toda otra persona humana o jurídica que:",o:["Opere exclusivamente en mercados del exterior, sin ofrecer ni colocar valores negociables en la Argentina","Ofrezca comprar, vender u operar valores que debieran contar con autorización de oferta pública y no la hubieran obtenido al momento de la operación","Haya sido condenada en sede penal por cualquier tipo de delito, aunque no se vincule con el mercado","Sea cliente de un agente registrado ante la CNV y haya operado valores con oferta pública autorizada"],a:1,e:"El sumario alcanza a cualquiera que ofrezca valores que necesitaban oferta pública autorizada y no la tenían.",r:"M1 · P98"},
{id:"M1-93",m:1,q:"El procedimiento sumarial abreviado del art. 140 de la Ley 26.831 NO resultará de aplicación, entre otras situaciones, cuando:",o:["El sumariado sea una persona humana y no una persona jurídica, cualquiera sea la conducta imputada","Los sumariados admitan los hechos y reconozcan expresamente las conductas infractoras y su responsabilidad","El infractor hubiera obtenido presuntamente un beneficio económico, o haya elementos de perjuicio económico a los inversores o al mercado","La infracción esté incluida en la Grilla de Conductas Infractoras pasibles de Procedimiento Sumarial Abreviado"],a:2,e:"El abreviado no va si hubo beneficio económico para el infractor o perjuicio para los inversores o el mercado.",r:"M1 · P99"},
{id:"M1-40",m:1,q:"Para que proceda el procedimiento de sumario abreviado, todos los sumariados deberán:",o:["Pagar previamente la multa mínima","Admitir los hechos y reconocer expresamente las conductas infractoras y su responsabilidad","Renunciar a su matrícula ante la CNV","Acreditar que no hubo perjuicio a terceros"],a:1,e:"El abreviado requiere que todos los sumariados admitan los hechos y reconozcan en forma expresa las conductas infractoras y su responsabilidad.",r:"M1 · P100"},
{id:"M1-124",m:1,q:"Las sanciones que se pueden imponer en el marco del procedimiento abreviado únicamente podrán consistir en:",o:["Multa y/o Apercibimiento","Apercibimiento y/o Suspensión","Multa y/o Inhabilitación","Suspensión y/o Revocación de la autorización"],a:0,e:"Según la guía, en el procedimiento abreviado las sanciones se limitan a multa y/o apercibimiento.",r:"M1 · P101"},
{id:"M1-125",m:1,q:"En los sumarios abreviados, en los casos donde resulta procedente la aplicación de Multa, la misma no podrá superar el monto de:",o:["Pesos un millón ($ 1.000.000)","Pesos cinco millones ($ 5.000.000)","Pesos diez millones ($ 10.000.000)","Pesos veinte millones ($ 20.000.000)"],a:2,e:"Según la guía, la multa en un sumario abreviado tiene un tope de $ 10.000.000.",r:"M1 · P102"},
{id:"M1-94",m:1,q:"Si se produjeran nuevos cargos durante la actividad sumarial:",o:["Pueden incluirse por resolución del Directorio si son incumplimientos en la presentación de la documentación o información periódica que motivó el sumario","No pueden incluirse en el sumario en curso: siempre debe abrirse un nuevo sumario por cada cargo","Puede incluirlos el conductor del sumario por sí solo, sin intervención del Directorio de la CNV","Pueden incluirse en cualquier caso, pero sólo con el consentimiento expreso del sumariado"],a:0,e:"Se suman al sumario en curso, por resolución del Directorio, cuando son incumplimientos de la misma información periódica que lo originó.",r:"M1 · P103"},
{id:"M1-95",m:1,q:"Durante la tramitación del sumario, los sumariados gozan, entre otros, del derecho a:",o:["Designar al conductor del sumario entre los funcionarios de la CNV","Recusar al conductor del sumario y a los integrantes del Directorio de la CNV","Suspender el sumario cada vez que apelen una providencia del conductor","Exigir que el sumario tramite ante el mercado donde operan habitualmente"],a:1,e:"Entre sus garantías está la de recusar tanto al conductor del sumario como a los directores de la CNV.",r:"M1 · P104"},
{id:"M1-41",m:1,q:"Ante una investigación originada por una denuncia, si el denunciante desiste, la CNV:",o:["Archiva las actuaciones sin más trámite","Continuará actuando de oficio hasta finalizar la investigación","Suspende el trámite por 90 días","Deriva el caso al mercado correspondiente"],a:1,e:"La denuncia sólo dispara la actividad: la CNV sigue de oficio aunque el denunciante desista.",r:"M1 · P105"},
{id:"M1-96",m:1,q:"Recibida una denuncia y efectuada su investigación, ésta podrá culminar con:",o:["Únicamente el archivo de las actuaciones, sin otra consecuencia para el denunciado","La aplicación directa de una multa al denunciado, sin necesidad de sumario previo","La derivación obligatoria de la denuncia a la justicia penal para que la investigue","Su desestimación si no se comprobaron las irregularidades, la instrucción de un sumario o un reporte de operación sospechosa"],a:3,e:"Tres salidas posibles: desestimar, instruir sumario o formular un reporte de operación sospechosa.",r:"M1 · P106"},
{id:"M1-126",m:1,q:"El denunciante será notificado del estado de su denuncia:",o:["Se le notificará cada paso del procedimiento","Se le notificará sólo si se instruye un sumario","No se le notificará, por el carácter reservado de la investigación","Se le notificará la decisión final"],a:3,e:"Según la guía, al denunciante se le notifica la decisión final sobre su denuncia, no cada etapa de la investigación.",r:"M1 · P107"},
{id:"M1-127",m:1,q:"La Comisión Nacional de Valores podrá iniciar investigaciones que se originen:",o:["Sólo por denuncias recibidas de inversores, ya que la CNV no puede actuar de oficio ni a partir de informaciones periodísticas","De oficio o por denuncias recibidas, pero nunca a partir de informaciones periodísticas, que no son una fuente válida","Por denuncias recibidas; de oficio, cuando advierta en ejercicio de sus funciones presuntas irregularidades administrativas; y a partir de informaciones periodísticas de las que surjan presuntas irregularidades","Únicamente por denuncias de un mercado o cámara compensadora, o por pedido expreso de la justicia penal"],a:2,e:"Según la guía, hay tres orígenes posibles: denuncias, actuación de oficio ante presuntas irregularidades y noticias periodísticas de las que surjan irregularidades.",r:"M1 · P108"},
{id:"M1-97",m:1,q:"Dentro de los objetivos establecidos por la Ley 26.831 se incluyen:",o:["Fortalecer la protección y prevención de abusos contra los inversores, propender a la inclusión financiera y a la integridad y transparencia de los mercados","Garantizar una rentabilidad mínima a los inversores minoristas y fijar precios de referencia para los valores negociables","Sustituir al BCRA en la regulación cambiaria y fijar las tasas de interés del sistema financiero","Reemplazar la autorregulación de los mercados por el control directo del Poder Ejecutivo"],a:0,e:"La ley apunta a proteger al inversor (función tuitiva del derecho del consumidor), a la inclusión financiera y a la transparencia del mercado.",r:"M1 · P109"},
{id:"M1-42",m:1,q:"¿Qué tipo de emisoras pueden adquirir sus propias acciones?",o:["Las sociedades anónimas que hacen oferta pública de acciones","Todas las sociedades bajo control de la CNV","Sólo las PyME CNV Garantizadas","Sólo las emisoras de obligaciones negociables"],a:0,e:"La recompra de acciones propias está prevista para las SA con oferta pública de acciones, respetando el trato igualitario.",r:"M1 · P110"},
{id:"M1-43",m:1,q:"¿Cuál de los siguientes se considera inversor calificado según la normativa vigente?",o:["Cualquier persona humana con más de 5 años de experiencia bursátil","El Estado Nacional, Provincias, Municipios, Cajas Previsionales y Compañías de Seguros","Todo titular de una cuenta comitente activa","Los idóneos inscriptos en el Registro de la CNV, en todos los casos"],a:1,e:"El listado incluye Estado y entes públicos, cajas previsionales, aseguradoras, reaseguradoras y ART, entre otros.",r:"M1 · P111"},
{id:"M1-98",m:1,q:"¿Cuál de las siguientes facultades está expresamente prevista en la Ley 26.831 como atribución de la CNV?",o:["Fijar las tasas de interés de las cauciones bursátiles y de los pases en los mercados","Garantizar el rendimiento de los fondos comunes de inversión frente a los cuotapartistas","Fijar normas mínimas de capacitación, acreditación y registro para quienes brinden asesoramiento al público inversor","Otorgar las licencias para operar a los bancos y demás entidades financieras"],a:2,e:"La CNV fija los estándares de quienes asesoran al público; no fija tasas ni garantiza rendimientos.",r:"M1 · P112"},
{id:"M1-44",m:1,q:"Las emisoras pueden celebrar asambleas de accionistas a distancia:",o:["Siempre que lo decida el directorio por mayoría simple","Siempre que esté previsto en el estatuto y se haya presentado el instructivo ante la CNV","Sólo durante emergencias declaradas por el Poder Ejecutivo","Nunca: la asamblea debe ser presencial"],a:1,e:"Doble requisito: previsión estatutaria + instructivo presentado ante la CNV.",r:"M1 · P113"},
{id:"M1-45",m:1,q:"La asamblea ordinaria que trate los asuntos del art. 234 incs. 1º y 2º de la Ley 19.550 deberá celebrarse:",o:["Dentro de los cuatro meses de la fecha de cierre del ejercicio","Dentro de los 70 días corridos del cierre","Dentro de los seis meses del cierre","En cualquier momento del ejercicio siguiente"],a:0,e:"4 meses desde el cierre de ejercicio para la asamblea ordinaria que trata estados contables y destino de resultados.",r:"M1 · P114"},
{id:"M1-99",m:1,q:"Agente de Custodia, Registro y Pago: ¿cuál es el objetivo principal de exigir plataformas de acceso libre para la información de pagos de instrumentos PyME?",o:["Restringir esa información a los inversores calificados para proteger a los minoristas","Permitir que el agente cobre un arancel razonable por el acceso a esa información","Garantizar acceso público gratuito y actualizado, reduciendo asimetrías informativas","Reemplazar la publicación de esos pagos en la Autopista de la Información Financiera"],a:2,e:"Que la información de pagos esté a mano de cualquiera, gratis y al día, achica la asimetría entre inversores.",r:"M1 · P115"},
{id:"M1-100",m:1,q:"Autorización Automática – Acciones: para acceder al mecanismo por Bajo/Mediano Impacto, el emisor debe:",o:["Estar admitido al Régimen General y cumplir condiciones específicas de impacto","Estar inscripto como PyME CNV Garantizada y contar con el aval de una SGR","Contar con al menos dos calificaciones de riesgo emitidas por agentes registrados","Tener sus acciones listadas previamente en un mercado del exterior"],a:0,e:"Según la guía, el requisito es doble: admisión al Régimen General y cumplir las condiciones de impacto.",r:"M1 · P116"},
{id:"M1-101",m:1,q:"Autorización Automática – FCI: un FCI puede obtener autorización automática cuando:",o:["Sea equivalente a un fondo de otra sociedad gerente que utiliza la misma depositaria","Su patrimonio inicial no supere 1.000.000 de UVA durante los primeros 12 meses","Sea un fondo cerrado con objeto inmobiliario y plazo de duración determinado","Sea sustancialmente equivalente a otro ya aprobado de la misma sociedad gerente, sin cambiar objetivo ni política de inversión"],a:3,e:"Si es un calco de un fondo que la misma gerente ya tiene aprobado, sin cambiar objetivo ni política, la autorización es automática.",r:"M1 · P117"},
{id:"M1-102",m:1,q:"Nuevo Título I – definiciones: ¿cuál fue un cambio central de la RG 1097/2025?",o:["La eliminación del régimen PyME CNV y su reemplazo por el régimen PyME CNV Garantizada","Unificación/actualización de definiciones transversales (Inversor Calificado, DUVA, PyME CNV, Ratio CEDEAR, Precio Equitativo)","La creación del régimen de Emisor Frecuente para emisores de obligaciones negociables","El traspaso del control societario de las emisoras al Registro Público de cada jurisdicción"],a:1,e:"La RG 1097/2025 ordenó en el Título I las definiciones que se usan en toda la normativa.",r:"M1 · P118"},
{id:"M1-103",m:1,q:"Fideicomisos Financieros: ¿a qué responde la simplificación de la RG 1084/2025?",o:["Simplificar y agilizar procesos de autorización/inscripción reduciendo requisitos","Endurecer los requisitos de autorización de los fideicomisos financieros para proteger al inversor","Prohibir la oferta pública de fideicomisos financieros con fiduciantes PyME","Exigir calificación de riesgo a todos los fideicomisos, sin excepción"],a:0,e:"La RG 1084/2025 fue en la dirección de agilizar: menos requisitos para autorizar e inscribir.",r:"M1 · P119"},
{id:"M1-104",m:1,q:"Oferta Privada: ¿qué elemento es clave para delimitar los destinatarios habilitados?",o:["El monto que invierte cada destinatario en la oferta","La residencia fiscal del destinatario, local o del exterior","La categoría del destinatario (Inversor Calificado o no calificado)","La antigüedad del destinatario como cliente del agente colocador"],a:2,e:"Los topes de la oferta privada se arman según el destinatario sea inversor calificado o no.",r:"M1 · P120"},
{id:"M1-105",m:1,q:"Mercados – difusión obligatoria: los mercados deben:",o:["Difundir los VN en circulación sólo a sus agentes miembros, a cambio de un arancel mensual","Implementar un mecanismo gratuito y permanente de difusión de los VN en circulación (datos identificatorios, fechas, montos y emisores)","Publicar los datos de los VN únicamente al momento de su emisión, en el aviso de colocación","Difundir en forma permanente la nómina de los tenedores de cada VN en circulación"],a:1,e:"La difusión tiene que ser gratuita y permanente, con los datos de cada valor en circulación y su emisor.",r:"M1 · P121"},
{id:"M1-106",m:1,q:"Representación Digital – alcance en el Título I:",o:["Eximir a los VN representados digitalmente de los requisitos de autorización de oferta pública","Equiparar cualquier activo virtual a un valor negociable, con o sin oferta pública","Reemplazar el prospecto por un documento técnico del token publicado por el emisor","Incorporar mecanismos basados en tecnología digital dentro del marco del VN, sin alterar los requisitos legales de oferta pública"],a:3,e:"Lo digital es una forma de representar el VN: los requisitos de oferta pública siguen siendo los mismos.",r:"M1 · P122"},
{id:"M1-107",m:1,q:"Tokenización – objetivo regulatorio:",o:["Eximir a los valores tokenizados de la regulación y fiscalización de la CNV","Prohibir la emisión de valores negociables en redes blockchain","Trasladar la supervisión de esos instrumentos a la UIF","Modernizar la operatoria del mercado mediante instrumentos digitales regulados"],a:3,e:"La tokenización busca modernizar el mercado, pero siempre con instrumentos regulados.",r:"M1 · P123"},
{id:"M1-108",m:1,q:"DUVA – finalidad según las definiciones 2025:",o:["Reemplazar la OPA por retiro voluntario por un trámite más simple ante la CNV","Estandarizar el concepto de DUVA y alinearlo con el retiro obligatorio y las participaciones residuales","Crear un nuevo tipo de valor negociable para los accionistas minoritarios","Fijar el precio equitativo de todas las OPA según una fórmula única"],a:1,e:"La definición 2025 unifica qué es la DUVA y la encaja con el retiro obligatorio y el régimen de participaciones residuales.",r:"M1 · P124"},
{id:"M1-46",m:1,q:"Una emisora hizo tres emisiones bajo OP Automática de Acciones en 12 meses por 2,2, 2,4 y 2,6 millones de UVA. ¿Califica una nueva emisión de 0,5 millones como Mediano Impacto?",o:["Sí, porque cada emisión se computa por separado","Sí, porque 0,5 millones está muy por debajo del tope","No, porque las emisiones se consideran parte de una misma oferta y el total superaría los 7 millones de UVA","No, porque el régimen exige un mínimo de 12 meses entre emisiones"],a:2,e:"7,2 millones acumulados > 7 millones de UVA. Todas las emisiones de los últimos 12 meses se suman como una sola oferta.",r:"M1 · P125"},
{id:"M1-36",m:1,q:"Una emisora planea colocar en Oferta Privada a 28 adquirentes (20 calificados y 8 no calificados). ¿Cumple el límite?",o:["No, porque supera los 15 adquirentes permitidos","Sí, porque no supera 35 adquirentes y los no calificados no exceden 15","No, porque los no calificados no pueden participar","Sí, pero debe informarlo previamente a la CNV"],a:1,e:"Los dos topes se controlan por separado: 35 adquirentes en total y 15 no calificados invitados.",r:"M1 · P126"},
{id:"M1-109",m:1,q:"Un Agente de Custodia, Registro y Pago publica la información de pagos de instrumentos PyME sólo para usuarios registrados. ¿Cumple la RG 1054/2025?",o:["Sí, porque la registración previa protege los datos personales de los inversores","Sí, siempre que el registro de usuarios sea gratuito","No, la plataforma debe ser de acceso libre y gratuito para el público inversor","No, porque esa información sólo puede publicarla la CNV"],a:2,e:"Pedir registración ya no es acceso libre: la información tiene que estar abierta y gratis para el público inversor.",r:"M1 · P127"}
);
